struct BIT {
    int n;
    vector<int> tree;
    BIT(int size) : n(size), tree(size + 2, 0) {}
    void add(int idx, int val) {
        idx++;
        while (idx <= n) {
            tree[idx] += val;
            idx += idx & -idx;
        }
    }
    int sum(int idx) {
        idx++;
        int res = 0;
        while (idx > 0) {
            res += tree[idx];
            idx -= idx & -idx;
        }
        return res;
    }
    int rangeSum(int l, int r) {
        return sum(r) - sum(l - 1);
    }
};

