/*
Sweep line with coordinate compression + Fenwick tree.

We are given axis-aligned segments (horizontal or vertical).
Count intersections between horizontal and vertical segments.

For each horizontal segment y = const, x in [x1, x2]:
  add event at x1: activate y
  add event at x2: deactivate y
For each vertical segment x = const, y in [y1, y2]:
  query how many active horizontals have y in [y1, y2]

To correctly count intersections at endpoints, process events at the same x in this order:
  1) add horizontal
  2) vertical query
  3) remove horizontal

This way a horizontal [x1, x2] is active for all x in [x1, x2], inclusive.
*/

public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    static class Event implements Comparable<Event> {
        long x;
        int type; // 0 = add, 1 = query, 2 = remove
        int y1, y2; // for add/remove: y1 used; for query: [y1, y2]

        Event(long x, int type, int y1, int y2) {
            this.x = x;
            this.type = type;
            this.y1 = y1;
            this.y2 = y2;
        }

        @Override
        public int compareTo(Event other) {
            if (x != other.x) return Long.compare(x, other.x);
            return Integer.compare(type, other.type);
        }
    }

    static class Fenwick {
        long[] bit;
        int n;

        Fenwick(int n) {
            this.n = n;
            bit = new long[n + 2];
        }

        void add(int idx, long delta) {
            for (int i = idx; i <= n; i += i & -i) bit[i] += delta;
        }

        long sum(int idx) {
            long res = 0;
            for (int i = idx; i > 0; i -= i & -i) res += bit[i];
            return res;
        }

        long rangeSum(int l, int r) {
            if (l > r) return 0;
            return sum(r) - sum(l - 1);
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int n;
        try {
            n = fs.nextInt();
        } catch (Exception e) {
            return;
        }

        List<long[]> segments = new ArrayList<>(n);
        List<Long> ys = new ArrayList<>();

        for (int i = 0; i < n; i++) {
            long x1 = fs.nextLong();
            long y1 = fs.nextLong();
            long x2 = fs.nextLong();
            long y2 = fs.nextLong();

            segments.add(new long[]{x1, y1, x2, y2});

            if (y1 == y2) {
                ys.add(y1);
            } else if (x1 == x2) {
                ys.add(y1);
                ys.add(y2);
            }
        }

        Collections.sort(ys);
        List<Long> uniq = new ArrayList<>();
        for (Long v : ys) {
            if (uniq.isEmpty() || !uniq.get(uniq.size() - 1).equals(v)) uniq.add(v);
        }

        List<Event> events = new ArrayList<>();

        for (long[] s : segments) {
            long x1 = s[0], y1 = s[1], x2 = s[2], y2 = s[3];

            if (y1 == y2) { // horizontal
                if (x1 > x2) {
                    long t = x1; x1 = x2; x2 = t;
                }
                int y = lowerBound(uniq, y1) + 1;
                events.add(new Event(x1, 0, y, y));
                events.add(new Event(x2, 2, y, y));
            } else if (x1 == x2) { // vertical
                if (y1 > y2) {
                    long t = y1; y1 = y2; y2 = t;
                }
                int l = lowerBound(uniq, y1) + 1;
                int r = lowerBound(uniq, y2) + 1;
                events.add(new Event(x1, 1, l, r));
            }
        }

        Collections.sort(events);

        Fenwick fw = new Fenwick(uniq.size());
        long ans = 0;

        for (Event e : events) {
            if (e.type == 0) {
                fw.add(e.y1, 1);
            } else if (e.type == 1) {
                ans += fw.rangeSum(e.y1, e.y2);
            } else {
                fw.add(e.y1, -1);
            }
        }

        System.out.println(ans);
    }

    static int lowerBound(List<Long> a, long x) {
        int l = 0, r = a.size();
        while (l < r) {
            int m = (l + r) >>> 1;
            if (a.get(m) < x) l = m + 1;
            else r = m;
        }
        return l;
    }
}

