    scanf("%d", &n);

    // Store segments: x1,y1,x2,y2
    long long *x1 = malloc(n * sizeof(long long));
    long long *y1 = malloc(n * sizeof(long long));
    long long *x2 = malloc(n * sizeof(long long));
    long long *y2 = malloc(n * sizeof(long long));

    for (int i = 0; i < n; i++) {
        scanf("%lld %lld %lld %lld", &x1[i], &y1[i], &x2[i], &y2[i]);
        // Normalize so x1<=x2, y1<=y2
        if (x1[i] > x2[i]) { long long t = x1[i]; x1[i] = x2[i]; x2[i] = t; }
        if (y1[i] > y2[i]) { long long t = y1[i]; y1[i] = y2[i]; y2[i] = t; }
    }

    long long count = 0;
    for (int i = 0; i < n; i++) {
        for (int j = i+1; j < n; j++) {
            int hi = (y1[i] == y2[i]); // segment i is horizontal
            int hj = (y1[j] == y2[j]); // segment j is horizontal

            if (hi && hj) {
                // Both horizontal
                if (y1[i] == y1[j]) {
                    // Same y, check x overlap
                    long long lo = x1[i] > x1[j] ? x1[i] : x1[j];
                    long long hi2 = x2[i] < x2[j] ? x2[i] : x2[j];
                    if (lo <= hi2) count++;
                }
            } else if (!hi && !hj) {
                // Both vertical
                if (x1[i] == x1[j]) {
                    long long lo = y1[i] > y1[j] ? y1[i] : y1[j];
                    long long hi2 = y2[i] < y2[j] ? y2[i] : y2[j];
                    if (lo <= hi2) count++;
                }
            } else {
                // One horizontal, one vertical
                int h = hi ? i : j;
                int v = hi ? j : i;
                // Horizontal: y=y1[h], x in [x1[h],x2[h]]
                // Vertical: x=x1[v], y in [y1[v],y2[v]]
                if (x1[h] <= x1[v] && x1[v] <= x2[h] &&
                    y1[v] <= y1[h] && y1[h] <= y2[v]) {
                    count++;
                }
            }
        }
    }

    printf("%lld\n", count);

    free(x1); free(y1); free(x2); free(y2);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

#define MAX_N 100000

typedef struct {
    int x, y;
} Point;

typedef struct {
    Point p1, p2;
} Segment;

typedef struct {
    int x, y1, y2;
} HorEvent;

typedef struct {
    int x, y, type; // type 1 = start, -1 = end
} VertEvent;

int cmp_hor(const void *a, const void *b) {
    return ((HorEvent*)a)->x - ((HorEvent*)b)->x;
}

int cmp_vert(const void *a, const void *b) {
    return ((VertEvent*)a)->x - ((VertEvent*)b)->x;
}

int bit[MAX_N * 2 + 5], n;

void update(int idx, int val) {
    while (idx <= n) {
        bit[idx] += val;
        idx += idx & -idx;
    }
}

int query(int idx) {
    int sum = 0;
    while (idx > 0) {
        sum += bit[idx];
        idx -= idx & -idx;
    }
    return sum;
}

int main() {
    int N;
    scanf("%d", &N);
    Segment segs[MAX_N];
    int ys[MAX_N * 2], ycnt = 0;
    int hor_count = 0, vert_count = 0;
    HorEvent hor[MAX_N];
    VertEvent vert[MAX_N * 2];

    for (int i = 0; i < N; i++) {
        scanf("%d %d %d %d", &segs[i].p1.x, &segs[i].p1.y, &segs[i].p2.x, &segs[i].p2.y);
        if (segs[i].p1.y == segs[i].p2.y) {
            if (segs[i].p1.x > segs[i].p2.x) {
                Point tmp = segs[i].p1;
                segs[i].p1 = segs[i].p2;
                segs[i].p2 = tmp;
            }
            hor[hor_count].x = segs[i].p1.x;
            hor[hor_count].y1 = segs[i].p1.y;
            hor[hor_count].y2 = segs[i].p2.y;
            hor_count++;
        } else {
            if (segs[i].p1.y > segs[i].p2.y) {
                Point tmp = segs[i].p1;
                segs[i].p1 = segs[i].p2;
                segs[i].p2 = tmp;
            }
            vert[vert_count].x = segs[i].p1.x;
            vert[vert_count].y = segs[i].p1.y;
            vert[vert_count].type = 1;
            vert_count++;
            vert[vert_count].x = segs[i].p2.x;
            vert[vert_count].y = segs[i].p2.y;
            vert[vert_count].type = -1;
            vert_count++;
        }
        ys[ycnt++] = segs[i].p1.y;
        ys[ycnt++] = segs[i].p2.y;
    }

    // Coordinate compression
    qsort(ys, ycnt, sizeof(int), (int(*)(const void*, const void*)) (int (*)(const void*, const void*)) 
        [](const void *a, const void *b) { return *(int*)a - *(int*)b; });
    int uniq = 0;
    for (int i = 0; i < ycnt; i++) {
        if (i == 0 || ys[i] != ys[i-1])
            ys[uniq++] = ys[i];
    }
    n = uniq;

    qsort(hor, hor_count, sizeof(HorEvent), cmp_hor);
    qsort(vert, vert_count, sizeof(VertEvent), cmp_vert);

    long long intersections = 0;
    int vptr = 0;

    for (int i = 0; i < hor_count; i++) {
        while (vptr < vert_count && vert[vptr].x < hor[i].x) {
            int yidx = (int)((long long*)bsearch(&vert[vptr].y, ys, n, sizeof(int), 
                [](const void *a, const void *b) { 
                    return *(int*)a - *(int*)b; 
                }) - (long long*)ys) + 1;
            update(yidx, vert[vptr].type);
            vptr++;
        }
        int y1idx = (int)((long long*)bsearch(&hor[i].y1, ys, n, sizeof(int), 
            [](const void *a, const void *b) { 
                return *(int*)a - *(int*)b; 
            }) - (long long*)ys) + 1;
        int y2idx = (int)((long long*)bsearch(&hor[i].y2, ys, n, sizeof(int), 
            [](const void *a, const void *b) { 
                return *(int*)a - *(int*)b; 
            }) - (long long*)ys) + 1;
        intersections += query(y2idx) - query(y1idx - 1);
    }

    printf("%lld\n", intersections);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

typedef long long ll;

typedef struct {
    int type;   /* 0 = add horizontal, 1 = query vertical, 2 = remove horizontal */
    ll x;
    ll y1, y2;
} Event;

typedef struct {
    ll x, y1, y2;
} Segment;

static int cmp_ll(const void *a, const void *b) {
    ll x = *(const ll *)a;
    ll y = *(const ll *)b;
    if (x < y) return -1;
    if (x > y) return 1;
    return 0;
}

static int cmp_event(const void *a, const void *b) {
    const Event *e1 = (const Event *)a;
    const Event *e2 = (const Event *)b;
    if (e1->x < e2->x) return -1;
    if (e1->x > e2->x) return 1;
    /* Order at same x: add -> query -> remove
       so intersections at endpoints are counted */
    if (e1->type < e2->type) return -1;
    if (e1->type > e2->type) return 1;
    return 0;
}

static int lower_bound_ll(ll *a, int n, ll x) {
    int l = 0, r = n;
    while (l < r) {
        int m = l + (r - l) / 2;
        if (a[m] < x) l = m + 1;
        else r = m;
    }
    return l;
}

typedef struct {
    int n;
    ll *bit;
} Fenwick;

static void bit_init(Fenwick *fw, int n) {
    fw->n = n;
    fw->bit = (ll *)calloc((size_t)(n + 1), sizeof(ll));
}

static void bit_add(Fenwick *fw, int idx, ll val) {
    while (idx <= fw->n) {
        fw->bit[idx] += val;
        idx += idx & -idx;
    }
}

static ll bit_sum(Fenwick *fw, int idx) {
    ll res = 0;
    while (idx > 0) {
        res += fw->bit[idx];
        idx -= idx & -idx;
    }
    return res;
}

static ll bit_range_sum(Fenwick *fw, int l, int r) {
    if (l > r) return 0;
    return bit_sum(fw, r) - bit_sum(fw, l - 1);
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    Segment *h = (Segment *)malloc((size_t)n * sizeof(Segment));
    Segment *v = (Segment *)malloc((size_t)n * sizeof(Segment));
    Event *events = (Event *)malloc((size_t)(3LL * n) * sizeof(Event));
    ll *ys = (ll *)malloc((size_t)(3LL * n) * sizeof(ll));

    int hc = 0, vc = 0, ec = 0, yc = 0;

    for (int i = 0; i < n; i++) {
        ll x1, y1, x2, y2;
        scanf("%lld %lld %lld %lld", &x1, &y1, &x2, &y2);

        if (x1 == x2) {
            if (y1 > y2) {
                ll t = y1; y1 = y2; y2 = t;
            }
            v[vc].x = x1;
            v[vc].y1 = y1;
            v[vc].y2 = y2;
            vc++;

            events[ec].type = 1;
            events[ec].x = x1;
            events[ec].y1 = y1;
            events[ec].y2 = y2;
            ec++;

            ys[yc++] = y1;
            ys[yc++] = y2;
        } else {
            if (x1 > x2) {
                ll t = x1; x1 = x2; x2 = t;
            }
            /* horizontal segment */
            h[hc].x = x1;
            h[hc].y1 = y1; /* actually y */
            h[hc].y2 = x2; /* actually right x */
            hc++;

            events[ec].type = 0;
            events[ec].x = x1;
            events[ec].y1 = y1;
            events[ec].y2 = 0;
            ec++;

            events[ec].type = 2;
            events[ec].x = x2;
            events[ec].y1 = y1;
            events[ec].y2 = 0;
            ec++;

            ys[yc++] = y1;
        }
    }

    qsort(ys, yc, sizeof(ll), cmp_ll);
    int m = 0;
    for (int i = 0; i < yc; i++) {
        if (i == 0 || ys[i] != ys[i - 1]) ys[m++] = ys[i];
    }

    qsort(events, ec, sizeof(Event), cmp_event);

    Fenwick fw;
    bit_init(&fw, m);

    ll ans = 0;

    for (int i = 0; i < ec; i++) {
        if (events[i].type == 0) {
            int y = lower_bound_ll(ys, m, events[i].y1) + 1;
            bit_add(&fw, y, 1);
        } else if (events[i].type == 2) {
            int y = lower_bound_ll(ys, m, events[i].y1) + 1;
            bit_add(&fw, y, -1);
        } else {
            int l = lower_bound_ll(ys, m, events[i].y1) + 1;
            int r = lower_bound_ll(ys, m, events[i].y2) + 1;
            ans += bit_range_sum(&fw, l, r);
        }
    }

    printf("%lld\n", ans);

    free(h);
    free(v);
    free(events);
    free(ys);
    free(fw.bit);
    return 0;
}
